function openChess(){showDialog('A SMALL DETOUR / CHESS',`<div class="chess-layout"><div class="chessboard" role="group" aria-label="Chess puzzle board"></div><div class="chess-copy"><p class="eyebrow">WHITE TO MOVE</p><h2 id="dialog-title">Two threats.<br>One move.</h2><p>Select the white knight, then the square that forks the black king and queen. This is a one-move puzzle.</p><p id="chess-status" role="status">Start with the knight on e5.</p><button class="text-link" id="chess-hint">A little hint <span>↗</span></button></div></div>`);let selected=false,solved=false;function board(){const pieces={h8:'♚',d8:'♛',g1:'♔',[solved?'f7':'e5']:'♘'};const names={h8:'black king',d8:'black queen',g1:'white king',[solved?'f7':'e5']:'white knight'};$('.chessboard').innerHTML=Array.from({length:64},(_,i)=>{const file='abcdefgh'[i%8],rank=8-Math.floor(i/8),sq=file+rank;return `<button class="square ${((i%8)+Math.floor(i/8))%2?'dark':''} ${selected&&sq==='e5'?'selected':''} ${solved&&['f7','d8','h8'].includes(sq)?'target':''}" data-square="${sq}" aria-label="${sq}${names[sq]?', '+names[sq]:', empty'}">${pieces[sq]||''}<small>${sq}</small></button>`}).join('');$$('[data-square]').forEach(b=>b.onclick=()=>{if(solved)return;if(b.dataset.square==='e5'){selected=true;board();$('#chess-status').textContent='Knight selected. Where should it go?';return}if(!selected){$('#chess-status').textContent='Select the white knight on e5 first.';return}if(b.dataset.square==='f7'){solved=true;board();$('#chess-status').textContent='Nf7+ — fork found. The knight attacks the king on h8 and queen on d8.'}else $('#chess-status').textContent='Not quite. Look for a knight move that attacks both h8 and d8.'})}board();$('#chess-hint').onclick=()=>$('#chess-status').textContent='A knight on f7 attacks both h8 and d8. Select e5, then f7.'}
